/// Callback or queue state that one camera command copies to report the end of
/// its transitions.
///
/// See `mln_camera_transition_handler` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html).
pub const CameraTransitionHandler = struct {
    context: ?*anyopaque = null,
    release_context: ?*const fn (?*anyopaque) void = null,
    callback: ?*const fn (context: ?*anyopaque, end: CameraTransitionEnd) anyerror!void = null,
    pub fn toNative(self: CameraTransitionHandler, roots: *callbacks.Roots) status.Error!c.mln_camera_transition_handler {
