        if (!(self.callback == null)) {
            const retained = try roots.retain(CameraTransitionHandler, self);
            raw.user_data = retained;
            raw.release_user_data = callbacks.Registration(CameraTransitionHandler).releaseNative;
        }
        return raw;
    }
    fn callbackTrampoline(native_arg_0: marshal.CallbackArg(c.mln_camera_transition_end_callback, 0), native_arg_1: marshal.CallbackArg(c.mln_camera_transition_end_callback, 1)) callconv(.c) marshal.CallbackResult(c.mln_camera_transition_end_callback) {
        return struct {
            fn invoke(callback_arg_0: marshal.CallbackArg(c.mln_camera_transition_end_callback, 0), callback_arg_1: marshal.CallbackArg(c.mln_camera_transition_end_callback, 1)) anyerror!marshal.CallbackResult(c.mln_camera_transition_end_callback) {
                const state = callbacks.Registration(CameraTransitionHandler).get(callback_arg_0);
                const host = state.value.callback orelse {
                    return;
                };
                try host(state.value.context, CameraTransitionEnd.fromNative((callback_arg_1 orelse return error.NativeError).*));
            }
