    /// Builds a `CameraTransitionHandler` whose callbacks receive `context`, a pointer, as
    /// its own type. Each callback takes the context and then the arguments
    /// of its field, and may return any error; pass null to leave one unset.
    /// Native runs `release`, when it is not null, once it releases the
    /// registration.
    pub fn init(context: anytype, comptime callback: anytype, comptime release: ?fn (@TypeOf(context)) void) CameraTransitionHandler {
        const Context = @TypeOf(context);
        if (@typeInfo(Context) != .pointer) @compileError("a CameraTransitionHandler context must be a pointer");
        return .{
            .context = @ptrCast(@constCast(context)),
            .release_context = if (release == null) null else struct {
                fn call(erased: ?*anyopaque) void {
                    release.?(@as(Context, @ptrCast(@alignCast(erased.?))));
                }
            }.call,
            .callback = if (@TypeOf(callback) == @TypeOf(null)) null else struct {
                fn call(erased: ?*anyopaque, argument_0: CameraTransitionEnd) anyerror!void {
                    return callback(@as(Context, @ptrCast(@alignCast(erased.?))), argument_0);
                }
            }.call,
