/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html).
pub const MapSnapshot = struct {
    /// Debug overlay mask of `mln_map_debug_flag` values.
    debug_options: MapDebugFlag = .{},
    generation: u64 = 0,
    /// True once every requested style and tile resource finished loading.
    fully_loaded: bool = false,
    rendering_stats_view_enabled: bool = false,
    /// True while the map is inside a gesture.
    gesture_in_progress: bool = false,
    /// True while a camera command with a duration is still animating.
    transition_in_progress: bool = false,
    event_mask: RuntimeEventFlag = .{},
    /// Generation of the latest render update the map published. A rendered
    /// frame at or past it draws map state that includes every command this
    /// snapshot observes, though animations and resource loads finish in later
    /// frames.
    latest_render_update_generation: u64 = 0,
    tile: MapTileOptions = .{},
    bounds: BoundOptions = .{},
    free_camera: FreeCameraOptions = .{},
    /// The map's camera, extent, projection mode, and viewport options.
    /// `mln_map_projection_create()` converts coordinates for this view.
    view: MapView = .{},
    pub fn fromNative(raw: c.mln_map_snapshot) MapSnapshot {
        return .{
            .debug_options = MapDebugFlag.fromNative(raw.debug_options),
            .generation = raw.generation,
            .fully_loaded = raw.fully_loaded,
            .rendering_stats_view_enabled = raw.rendering_stats_view_enabled,
            .gesture_in_progress = raw.gesture_in_progress,
            .transition_in_progress = raw.transition_in_progress,
            .event_mask = RuntimeEventFlag.fromNative(raw.event_mask),
            .latest_render_update_generation = raw.latest_render_update_generation,
            .tile = MapTileOptions.fromNative(raw.tile),
            .bounds = BoundOptions.fromNative(raw.bounds),
            .free_camera = FreeCameraOptions.fromNative(raw.free_camera),
            .view = MapView.fromNative(raw.view),
        };
    }
};

/// Tile prefetch and LOD tuning controls.
///
/// See `mln_map_tile_options` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html).
pub const MapTileOptions = struct {
    /// Prefetch zoom delta, at most 255.
    prefetch_zoom_delta: ?u32 = null,
    lod_min_radius: ?f64 = null,
    lod_scale: ?f64 = null,
    lod_pitch_threshold: ?f64 = null,
    lod_zoom_shift: ?f64 = null,
    lod_mode: ?TileLodMode = null,
    pub fn toNative(self: MapTileOptions) c.mln_map_tile_options {
        var raw = std.mem.zeroes(c.mln_map_tile_options);
        raw.fields = 0;
        raw.size = @sizeOf(c.mln_map_tile_options);
        marshal.present(&raw.fields, c.MLN_MAP_TILE_OPTION_PREFETCH_ZOOM_DELTA, &raw.prefetch_zoom_delta, self.prefetch_zoom_delta);
        marshal.present(&raw.fields, c.MLN_MAP_TILE_OPTION_LOD_MIN_RADIUS, &raw.lod_min_radius, self.lod_min_radius);
        marshal.present(&raw.fields, c.MLN_MAP_TILE_OPTION_LOD_SCALE, &raw.lod_scale, self.lod_scale);
        marshal.present(&raw.fields, c.MLN_MAP_TILE_OPTION_LOD_PITCH_THRESHOLD, &raw.lod_pitch_threshold, self.lod_pitch_threshold);
        marshal.present(&raw.fields, c.MLN_MAP_TILE_OPTION_LOD_ZOOM_SHIFT, &raw.lod_zoom_shift, self.lod_zoom_shift);
        marshal.present(&raw.fields, c.MLN_MAP_TILE_OPTION_LOD_MODE, &raw.lod_mode, self.lod_mode);
        return raw;
    }
    pub fn fromNative(raw: c.mln_map_tile_options) MapTileOptions {
        return .{
            .prefetch_zoom_delta = if (raw.fields & c.MLN_MAP_TILE_OPTION_PREFETCH_ZOOM_DELTA != 0) raw.prefetch_zoom_delta else null,
            .lod_min_radius = if (raw.fields & c.MLN_MAP_TILE_OPTION_LOD_MIN_RADIUS != 0) raw.lod_min_radius else null,
            .lod_scale = if (raw.fields & c.MLN_MAP_TILE_OPTION_LOD_SCALE != 0) raw.lod_scale else null,
            .lod_pitch_threshold = if (raw.fields & c.MLN_MAP_TILE_OPTION_LOD_PITCH_THRESHOLD != 0) raw.lod_pitch_threshold else null,
            .lod_zoom_shift = if (raw.fields & c.MLN_MAP_TILE_OPTION_LOD_ZOOM_SHIFT != 0) raw.lod_zoom_shift else null,
            .lod_mode = if (raw.fields & c.MLN_MAP_TILE_OPTION_LOD_MODE != 0) TileLodMode.fromNative(raw.lod_mode) else null,
        };
    }
};

/// Everything that a projection depends on: the transform that a published
/// snapshot or a rendered frame describes.
///
/// See `mln_map_view` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html).
pub const MapView = struct {
    /// The camera. Its center is unwrapped: the longitude keeps the visible
    /// world copy and may fall outside -180 to 180.
    camera: Camera = .{},
    /// Logical size and device-pixel scale. A snapshot carries the map's scale
    /// factor, and a frame carries the scale factor of the target that drew it.
    extent: LogicalExtent = .{},
    /// Axonometric mode and skew, with every field set.
    projection_mode: ProjectionMode = .{},
    /// North orientation, constrain mode, viewport mode, and frustum offset,
    /// with every field set.
    viewport: MapViewportOptions = .{},
    pub fn toNative(self: MapView) c.mln_map_view {
        var raw = std.mem.zeroes(c.mln_map_view);
        raw.size = @sizeOf(c.mln_map_view);
        raw.camera = self.camera.toNative();
        raw.extent = self.extent.toNative();
        raw.projection_mode = self.projection_mode.toNative();
        raw.viewport = self.viewport.toNative();
        return raw;
    }
    pub fn fromNative(raw: c.mln_map_view) MapView {
        return .{
            .camera = Camera.fromNative(raw.camera),
            .extent = LogicalExtent.fromNative(raw.extent),
            .projection_mode = ProjectionMode.fromNative(raw.projection_mode),
            .viewport = MapViewportOptions.fromNative(raw.viewport),
        };
    }
};

/// Live map viewport and render-transform controls.
///
/// See `mln_map_viewport_options` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html).
pub const MapViewportOptions = struct {
    north_orientation: ?NorthOrientation = null,
    constrain_mode: ?ConstrainMode = null,
    viewport_mode: ?ViewportMode = null,
    frustum_offset: ?EdgeInsets = null,
    pub fn toNative(self: MapViewportOptions) c.mln_map_viewport_options {
        var raw = std.mem.zeroes(c.mln_map_viewport_options);
        raw.fields = 0;
        raw.size = @sizeOf(c.mln_map_viewport_options);
        marshal.present(&raw.fields, c.MLN_MAP_VIEWPORT_OPTION_NORTH_ORIENTATION, &raw.north_orientation, self.north_orientation);
        marshal.present(&raw.fields, c.MLN_MAP_VIEWPORT_OPTION_CONSTRAIN_MODE, &raw.constrain_mode, self.constrain_mode);
        marshal.present(&raw.fields, c.MLN_MAP_VIEWPORT_OPTION_VIEWPORT_MODE, &raw.viewport_mode, self.viewport_mode);
        marshal.present(&raw.fields, c.MLN_MAP_VIEWPORT_OPTION_FRUSTUM_OFFSET, &raw.frustum_offset, self.frustum_offset);
        return raw;
    }
    pub fn fromNative(raw: c.mln_map_viewport_options) MapViewportOptions {
        return .{
            .north_orientation = if (raw.fields & c.MLN_MAP_VIEWPORT_OPTION_NORTH_ORIENTATION != 0) NorthOrientation.fromNative(raw.north_orientation) else null,
            .constrain_mode = if (raw.fields & c.MLN_MAP_VIEWPORT_OPTION_CONSTRAIN_MODE != 0) ConstrainMode.fromNative(raw.constrain_mode) else null,
            .viewport_mode = if (raw.fields & c.MLN_MAP_VIEWPORT_OPTION_VIEWPORT_MODE != 0) ViewportMode.fromNative(raw.viewport_mode) else null,
            .frustum_offset = if (raw.fields & c.MLN_MAP_VIEWPORT_OPTION_FRUSTUM_OFFSET != 0) EdgeInsets.fromNative(raw.frustum_offset) else null,
        };
    }
};

/// One caller-owned Metal texture of a borrowed texture ring.
///
/// See `mln_metal_borrowed_texture` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/texture_8h.html).
pub const MetalBorrowedTexture = struct {
    /// Borrowed `id<MTLTexture>` / `MTL::Texture*`. Required.
    texture: ?*anyopaque,
    pub fn toNative(self: MetalBorrowedTexture) c.mln_metal_borrowed_texture {
        var raw = std.mem.zeroes(c.mln_metal_borrowed_texture);
        raw.texture = self.texture;
        return raw;
    }
    pub fn fromNative(raw: c.mln_metal_borrowed_texture) MetalBorrowedTexture {
        return .{
            .texture = raw.texture,
        };
    }
};

/// Metal attachment options for a borrowed texture target.
///
/// See `mln_metal_borrowed_texture_descriptor` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/texture_8h.html).
pub const MetalBorrowedTextureDescriptor = struct {
    /// Logical texture extent. Required. physical_width and physical_height
    /// give the texture's size. A scale_factor that differs from the map's is
    /// accepted and logged as a warning.
    extent: LogicalExtent,
    /// Physical texture width in device pixels. Required.
    physical_width: u32,
    /// Physical texture height in device pixels. Required.
    physical_height: u32,
    /// The ring's textures, one per slot, in slot order. Required.
    textures: []const MetalBorrowedTexture,
    pub fn toNative(self: MetalBorrowedTextureDescriptor, allocator: std.mem.Allocator) status.Error!c.mln_metal_borrowed_texture_descriptor {
        var raw = std.mem.zeroes(c.mln_metal_borrowed_texture_descriptor);
        raw.size = @sizeOf(c.mln_metal_borrowed_texture_descriptor);
        raw.extent = self.extent.toNative();
        raw.physical_width = self.physical_width;
        raw.physical_height = self.physical_height;
        raw.textures = blk: {
            const items = try allocator.alloc(c.mln_metal_borrowed_texture, self.textures.len);
            for (self.textures, 0..) |array_item_0, index| items[index] = array_item_0.toNative();
            break :blk items.ptr;
        };
        raw.texture_count = std.math.cast(@TypeOf(raw.texture_count), self.textures.len) orelse return error.InvalidArgument;
        return raw;
    }

    pub fn fromNative(allocator: std.mem.Allocator, raw: c.mln_metal_borrowed_texture_descriptor) status.Error!MetalBorrowedTextureDescriptor {
        return .{
            .extent = LogicalExtent.fromNative(raw.extent),
            .physical_width = raw.physical_width,
            .physical_height = raw.physical_height,
            .textures = blk: {
                const copied = try allocator.alloc(MetalBorrowedTexture, raw.texture_count);
                for (try marshal.nativeSlice(c.mln_metal_borrowed_texture, raw.textures, raw.texture_count), 0..) |item, index| copied[index] = MetalBorrowedTexture.fromNative(item);
                break :blk copied;
            },
        };
    }
};

