/// Geometry offline region definition.
///
/// See `mln_offline_geometry_region_definition` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html).
pub const OfflineGeometryRegionDefinition = struct {
    /// Style URL. Copied during region creation.
    style_url: []const u8 = &.{},
    /// UTF-8 GeoJSON Geometry bytes. Required. Borrowed during region creation.
    geometry: []const u8,
    min_zoom: f64 = 0,
    /// Maximum zoom. Positive infinity lets each tile source use its own
    /// maximum zoom.
    max_zoom: f64 = 0,
    pixel_ratio: f32 = 0,
    include_ideographs: bool = false,
    pub fn toNative(self: OfflineGeometryRegionDefinition) status.Error!c.mln_offline_geometry_region_definition {
        var raw = std.mem.zeroes(c.mln_offline_geometry_region_definition);
        raw.style_url = marshal.view(self.style_url);
        raw.geometry = marshal.view(self.geometry);
        raw.min_zoom = self.min_zoom;
        raw.max_zoom = self.max_zoom;
        raw.pixel_ratio = self.pixel_ratio;
        raw.include_ideographs = self.include_ideographs;
        return raw;
    }

    pub fn fromNative(allocator: std.mem.Allocator, raw: c.mln_offline_geometry_region_definition) status.Error!OfflineGeometryRegionDefinition {
        return .{
            .style_url = try marshal.copyView(allocator, raw.style_url),
            .geometry = try marshal.copyView(allocator, raw.geometry),
            .min_zoom = raw.min_zoom,
            .max_zoom = raw.max_zoom,
            .pixel_ratio = raw.pixel_ratio,
            .include_ideographs = raw.include_ideographs,
        };
    }
};

/// Tagged offline region definition.
///
/// See `mln_offline_region_definition` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html).
pub const OfflineRegionDefinition = union(enum) {
    tile_pyramid: OfflineTilePyramidRegionDefinition,
    geometry: OfflineGeometryRegionDefinition,
    unknown: u32,

    pub fn toNative(self: OfflineRegionDefinition) status.Error!c.mln_offline_region_definition {
        var raw = std.mem.zeroes(c.mln_offline_region_definition);
        raw.size = @sizeOf(c.mln_offline_region_definition);
        switch (self) {
            .tile_pyramid => |item| {
                raw.type = c.MLN_OFFLINE_REGION_DEFINITION_TILE_PYRAMID;
                raw.data.tile_pyramid = try item.toNative();
            },
            .geometry => |item| {
                raw.type = c.MLN_OFFLINE_REGION_DEFINITION_GEOMETRY;
                raw.data.geometry = try item.toNative();
            },
            .unknown => return error.InvalidArgument,
        }
        return raw;
    }

    pub fn fromNative(allocator: std.mem.Allocator, raw: c.mln_offline_region_definition) status.Error!OfflineRegionDefinition {
        return switch (raw.type) {
            c.MLN_OFFLINE_REGION_DEFINITION_TILE_PYRAMID => .{ .tile_pyramid = try OfflineTilePyramidRegionDefinition.fromNative(allocator, raw.data.tile_pyramid) },
            c.MLN_OFFLINE_REGION_DEFINITION_GEOMETRY => .{ .geometry = try OfflineGeometryRegionDefinition.fromNative(allocator, raw.data.geometry) },
            else => |tag| .{ .unknown = @intCast(tag) },
        };
    }
};

