/// Host lock on the graphics queue that a session shares with its host, copied
/// by a successful attach.
///
/// See `mln_queue_lock` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/render__target_8h.html).
pub const QueueLock = struct {
    context: ?*anyopaque = null,
    release_context: ?*const fn (?*anyopaque) void = null,
    lock: ?*const fn (context: ?*anyopaque) anyerror!void = null,
    unlock: ?*const fn (context: ?*anyopaque) anyerror!void = null,
    pub fn toNative(self: QueueLock, roots: *callbacks.Roots) status.Error!c.mln_queue_lock {
        var raw = std.mem.zeroes(c.mln_queue_lock);
        raw.lock = if (self.lock != null) lockTrampoline else null;
        raw.unlock = if (self.unlock != null) unlockTrampoline else null;
        if (!(self.lock == null and self.unlock == null)) {
            const retained = try roots.retain(QueueLock, self);
            raw.user_data = retained;
            raw.release_user_data = callbacks.Registration(QueueLock).releaseNative;
        }
        return raw;
    }
    fn lockTrampoline(native_arg_0: marshal.CallbackArg(c.mln_queue_lock_callback, 0)) callconv(.c) marshal.CallbackResult(c.mln_queue_lock_callback) {
        return struct {
            fn invoke(callback_arg_0: marshal.CallbackArg(c.mln_queue_lock_callback, 0)) anyerror!marshal.CallbackResult(c.mln_queue_lock_callback) {
                const state = callbacks.Registration(QueueLock).get(callback_arg_0);
                const host = state.value.lock orelse {
                    return;
                };
                try host(state.value.context);
            }
        }.invoke(native_arg_0) catch |err| {
            callbacks.reportError("mln_queue_lock_callback", err);
            return;
        };
    }
    fn unlockTrampoline(native_arg_0: marshal.CallbackArg(c.mln_queue_lock_callback, 0)) callconv(.c) marshal.CallbackResult(c.mln_queue_lock_callback) {
        return struct {
            fn invoke(callback_arg_0: marshal.CallbackArg(c.mln_queue_lock_callback, 0)) anyerror!marshal.CallbackResult(c.mln_queue_lock_callback) {
                const state = callbacks.Registration(QueueLock).get(callback_arg_0);
                const host = state.value.unlock orelse {
                    return;
                };
                try host(state.value.context);
            }
        }.invoke(native_arg_0) catch |err| {
            callbacks.reportError("mln_queue_lock_callback", err);
            return;
        };
    }
    /// Builds a `QueueLock` whose callbacks receive `context`, a pointer, as
    /// its own type. Each callback takes the context and then the arguments
    /// of its field, and may return any error; pass null to leave one unset.
    /// Native runs `release`, when it is not null, once it releases the
    /// registration.
    pub fn init(context: anytype, comptime lock: anytype, comptime unlock: anytype, comptime release: ?fn (@TypeOf(context)) void) QueueLock {
        const Context = @TypeOf(context);
        if (@typeInfo(Context) != .pointer) @compileError("a QueueLock context must be a pointer");
        return .{
            .context = @ptrCast(@constCast(context)),
            .release_context = if (release == null) null else struct {
                fn call(erased: ?*anyopaque) void {
                    release.?(@as(Context, @ptrCast(@alignCast(erased.?))));
                }
            }.call,
            .lock = if (@TypeOf(lock) == @TypeOf(null)) null else struct {
                fn call(erased: ?*anyopaque) anyerror!void {
                    return lock(@as(Context, @ptrCast(@alignCast(erased.?))));
                }
            }.call,
            .unlock = if (@TypeOf(unlock) == @TypeOf(null)) null else struct {
                fn call(erased: ?*anyopaque) anyerror!void {
                    return unlock(@as(Context, @ptrCast(@alignCast(erased.?))));
                }
            }.call,
        };
    }
};

/// What abandon did with a session's graphics resources.
///
/// See `mln_render_abandon_disposition` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/render__session_8h.html).
pub const RenderAbandonDisposition = enum(u32) {
    /// Abandon destroyed every graphics resource, or none remained.
    clean = 0,
    /// Abandon kept graphics resources that it could not safely destroy.
    quarantined = 1,
    _,
    pub const fromNative = marshal.EnumMethods(@This()).fromNative;
    pub const toNative = marshal.EnumMethods(@This()).toNative;
};

pub const RenderAbandonResult = struct {
    disposition: RenderAbandonDisposition = .clean,
    /// Backend resource groups intentionally retained until process exit.
    quarantined_resource_count: u32 = 0,
    pub fn fromNative(raw: c.mln_render_abandon_result) RenderAbandonResult {
        return .{
            .disposition = RenderAbandonDisposition.fromNative(raw.disposition),
            .quarantined_resource_count = raw.quarantined_resource_count,
        };
    }
};

/// Render backend support flags reported by this native library build.
///
/// See `mln_render_backend_flag` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/base_8h.html).
pub const RenderBackendFlag = struct {
    metal: bool = false,
    vulkan: bool = false,
    opengl: bool = false,
    webgpu: bool = false,
    unknown_bits: u32 = 0,
    pub const native_bits = [_]u32{ 1, 2, 4, 8 };
    const methods = marshal.FlagMethods(@This());
    pub const fromNative = methods.fromNative;
    pub const toNative = methods.toNative;
};

/// Execution placement for one render session.
///
/// See `mln_render_driver_kind` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/render__target_8h.html).
pub const RenderDriverKind = enum(u32) {
    /// Native code initializes, services, and tears down transferable graphics
    /// state on a library-owned thread.
    core_worker = 1,
    /// The host services driver work on the thread or realm where its graphics
    /// context is current.
    caller_graphics_thread = 2,
    _,
    pub const fromNative = marshal.EnumMethods(@This()).fromNative;
    pub const toNative = marshal.EnumMethods(@This()).toNative;
};

/// Terminal result of one frame demand, held by an owned frame-result batch and
/// copied by `mln_acquired_frame_get_result()`.
///
/// See `mln_render_frame_result` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/render__session_8h.html).
pub const RenderFrameResult = struct {
    disposition: RenderResult = .rendered,
    token: u64 = 0,
    /// Generation of the map render update the demand evaluated. When
    /// disposition is `MLN_RENDER_RESULT_RENDERED`, the frame drew that update;
    /// compare it with `mln_completion_result.render_update_generation` to find
    /// the first frame that includes a command.
    map_update_generation: u64 = 0,
    /// The session's target generation when the demand reached its result. See
    /// `mln_render_session_snapshot.generation`.
    generation: u64 = 0,
    /// Position of the frame among the frames that the session rendered,
    /// counting from one. Zero unless disposition is
    /// `MLN_RENDER_RESULT_RENDERED`.
    frame_generation: u64 = 0,
    /// Whether the map asked for another frame while it rendered this one, as
    /// during an ongoing paint transition. Set only when disposition is
    /// `MLN_RENDER_RESULT_RENDERED`, and false for every other outcome. It
    /// matches the needs_repaint field of
    /// `MLN_RUNTIME_EVENT_MAP_RENDER_FRAME_FINISHED`. A camera transition does
    /// not set it: the map publishes an update for each of the transition's
    /// frames instead, which a render-if-needed demand renders.
    needs_repaint: bool = false,
    /// The view that this frame drew, from the transform of the map update that
    /// it rendered. A host that displays the frame builds its projection with
    /// `mln_map_projection_create()` to place overlays where the frame drew
    /// their coordinates. Zero, with a size of zero, unless disposition is
    /// `MLN_RENDER_RESULT_RENDERED`.
    view: MapView = .{},
    pub fn fromNative(raw: c.mln_render_frame_result) RenderFrameResult {
        return .{
            .disposition = RenderResult.fromNative(raw.disposition),
            .token = raw.token,
            .map_update_generation = raw.map_update_generation,
            .generation = raw.generation,
            .frame_generation = raw.frame_generation,
            .needs_repaint = raw.needs_repaint,
            .view = MapView.fromNative(raw.view),
        };
    }
};

/// Render modes reported by render observer events.
///
/// See `mln_render_mode` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/runtime_8h.html).
pub const RenderMode = enum(u32) {
    partial = 0,
    full = 1,
    _,
    pub const fromNative = marshal.EnumMethods(@This()).fromNative;
    pub const toNative = marshal.EnumMethods(@This()).toNative;
};

/// Terminal disposition of one accepted frame demand.
///
/// See `mln_render_result` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/render__session_8h.html).
pub const RenderResult = enum(u32) {
    /// A frame was rendered for acquisition, presentation, or ordered readback.
    rendered = 0,
    /// No newer map update was available, the map had no complete frame to
    /// draw, or the update extent differed from the target. The map publishes
    /// another update when it has one. A demand with
    /// `MLN_FRAME_DEMAND_WAIT_FOR_UPDATE` waits for that update instead, and
    /// finishes with this result only when a barrier ends its wait.
    no_update = 1,
    /// The target could not produce a frame. The attempt consumes nothing, so a
    /// later demand with the same flags renders what this one would have. This
    /// result does not cause a map update, so the host demands again when the
    /// target can be ready, such as after a paced delay.
    target_not_ready = 2,
    /// A newer demand with the same flags, neither of them forced, replaced
    /// this demand. A still image's demand is never replaced, and never
    /// replaces one.
    superseded = 3,
    _,
    pub const fromNative = marshal.EnumMethods(@This()).fromNative;
    pub const toNative = marshal.EnumMethods(@This()).toNative;
};

/// Common attachment policy copied before an attach call returns.
///
/// See `mln_render_session_attach_options` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/render__target_8h.html).
pub const RenderSessionAttachOptions = struct {
    /// Where the session's driver runs. Required.
    driver: RenderDriverKind,
    /// Requested slot count of a session-owned texture ring, up to
    /// `MLN_TEXTURE_RING_MAX_DEPTH`. Zero selects 2, so the host can retain one
    /// frame while the session renders its replacement. Private targets grant
    /// one slot regardless of this value. A borrowed texture ring's depth is
    /// its texture count, so borrowed and other targets ignore this value.
    requested_texture_ring_depth: u32 = 0,
    /// Producer synchronization for acquired texture frames.
    /// `MLN_GPU_SYNC_OPENGL_FENCE` requires a shared EGL or WGL texture target
    /// and a caller-graphics-thread driver. Other targets support only CPU
    /// completion and fail an unsupported request.
    producer_sync_kind: GpuSyncKind = .cpu_complete,
    /// Wakes the receiver when the frame-result queue becomes nonempty.
    frame_wake: Wake = .{},
    /// Wakes the graphics receiver when caller-driver work is available,
    /// including work that a finished driver result releases.
    driver_work_wake: Wake = .{},
    /// Host lock on the graphics queue, disabled by default. Only Vulkan
    /// targets accept an enabled lock; other backends fail the attach with
    /// `MLN_STATUS_UNSUPPORTED`.
    queue_lock: QueueLock = .{},
    pub fn toNative(self: RenderSessionAttachOptions, roots: *callbacks.Roots) status.Error!c.mln_render_session_attach_options {
        var raw = std.mem.zeroes(c.mln_render_session_attach_options);
        raw.size = @sizeOf(c.mln_render_session_attach_options);
        raw.driver = self.driver.toNative();
        raw.requested_texture_ring_depth = self.requested_texture_ring_depth;
        raw.producer_sync_kind = self.producer_sync_kind.toNative();
        raw.frame_wake = try self.frame_wake.toNative(roots);
        raw.driver_work_wake = try self.driver_work_wake.toNative(roots);
        raw.queue_lock = try self.queue_lock.toNative(roots);
        return raw;
    }

    pub fn fromNative(allocator: std.mem.Allocator, raw: c.mln_render_session_attach_options) status.Error!RenderSessionAttachOptions {
        _ = allocator;
        return .{
            .driver = RenderDriverKind.fromNative(raw.driver),
            .requested_texture_ring_depth = raw.requested_texture_ring_depth,
            .producer_sync_kind = GpuSyncKind.fromNative(raw.producer_sync_kind),
            .frame_wake = .{},
            .driver_work_wake = .{},
            .queue_lock = .{},
        };
    }
};

