/// Options for rendered feature queries.
///
/// See `mln_rendered_feature_query_options` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/query_8h.html).
pub const RenderedFeatureQueryOptions = struct {
    /// Optional style layer IDs. When absent, all rendered layers are queried.
    layer_ids: ?[]const []const u8 = null,
    /// UTF-8 MapLibre style-spec filter JSON, or empty for no filter.
    filter: []const u8 = &.{},
    pub fn toNative(self: RenderedFeatureQueryOptions, allocator: std.mem.Allocator) status.Error!c.mln_rendered_feature_query_options {
        var raw = std.mem.zeroes(c.mln_rendered_feature_query_options);
        raw.fields = 0;
        raw.size = @sizeOf(c.mln_rendered_feature_query_options);
        if (self.layer_ids) |item| {
            raw.fields |= c.MLN_RENDERED_FEATURE_QUERY_OPTION_LAYER_IDS;
            raw.layer_ids = blk: {
                const items = try allocator.alloc(c.mln_buffer_view, item.len);
                for (item, 0..) |array_item_0, index| items[index] = marshal.view(array_item_0);
                break :blk items.ptr;
            };
        }
        raw.layer_id_count = std.math.cast(@TypeOf(raw.layer_id_count), if (self.layer_ids) |items| items.len else 0) orelse return error.InvalidArgument;
        raw.filter = marshal.view(self.filter);
        return raw;
    }

    pub fn fromNative(allocator: std.mem.Allocator, raw: c.mln_rendered_feature_query_options) status.Error!RenderedFeatureQueryOptions {
        return .{
            .layer_ids = if (raw.fields & c.MLN_RENDERED_FEATURE_QUERY_OPTION_LAYER_IDS != 0) blk: {
                const copied = try allocator.alloc([]const u8, raw.layer_id_count);
                for (try marshal.nativeSlice(c.mln_buffer_view, raw.layer_ids, raw.layer_id_count), 0..) |item, index| copied[index] = try marshal.copyView(allocator, item);
                break :blk copied;
            } else null,
            .filter = try marshal.copyView(allocator, raw.filter),
        };
    }
};

/// Rendered feature query geometry descriptor.
///
/// See `mln_rendered_query_geometry` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/query_8h.html).
pub const RenderedQueryGeometry = union(enum) {
    point: ScreenPoint,
    box: ScreenBox,
    line_string: ScreenLineString,

    pub fn toNative(self: RenderedQueryGeometry, allocator: std.mem.Allocator) status.Error!c.mln_rendered_query_geometry {
        var raw = std.mem.zeroes(c.mln_rendered_query_geometry);
        raw.size = @sizeOf(c.mln_rendered_query_geometry);
        switch (self) {
            .point => |item| {
                raw.type = c.MLN_RENDERED_QUERY_GEOMETRY_TYPE_POINT;
                raw.data.point = item.toNative();
            },
            .box => |item| {
                raw.type = c.MLN_RENDERED_QUERY_GEOMETRY_TYPE_BOX;
                raw.data.box = item.toNative();
            },
            .line_string => |item| {
                raw.type = c.MLN_RENDERED_QUERY_GEOMETRY_TYPE_LINE_STRING;
                raw.data.line_string = try item.toNative(allocator);
            },
        }
        return raw;
    }

    pub fn fromNative(allocator: std.mem.Allocator, raw: c.mln_rendered_query_geometry) status.Error!RenderedQueryGeometry {
        return switch (raw.type) {
            c.MLN_RENDERED_QUERY_GEOMETRY_TYPE_POINT => .{ .point = ScreenPoint.fromNative(raw.data.point) },
            c.MLN_RENDERED_QUERY_GEOMETRY_TYPE_BOX => .{ .box = ScreenBox.fromNative(raw.data.box) },
            c.MLN_RENDERED_QUERY_GEOMETRY_TYPE_LINE_STRING => .{ .line_string = try ScreenLineString.fromNative(allocator, raw.data.line_string) },
            else => return error.NativeError,
        };
    }
};

