/// Global style transition options.
///
/// See `mln_style_transition_options` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/style_8h.html).
pub const StyleTransitionOptions = struct {
    /// Transition duration in milliseconds. Must be finite, non-negative, and
    /// short enough to represent as a duration.
    duration_ms: ?f64 = null,
    /// Transition delay in milliseconds. Must be finite, non-negative, and
    /// short enough to represent as a duration.
    delay_ms: ?f64 = null,
    /// Whether symbol placement changes cross-fade.
    enable_placement_transitions: ?bool = null,
    pub fn toNative(self: StyleTransitionOptions) c.mln_style_transition_options {
        var raw = std.mem.zeroes(c.mln_style_transition_options);
        raw.fields = 0;
        raw.size = @sizeOf(c.mln_style_transition_options);
        marshal.present(&raw.fields, c.MLN_STYLE_TRANSITION_OPTION_DURATION, &raw.duration_ms, self.duration_ms);
        marshal.present(&raw.fields, c.MLN_STYLE_TRANSITION_OPTION_DELAY, &raw.delay_ms, self.delay_ms);
        marshal.present(&raw.fields, c.MLN_STYLE_TRANSITION_OPTION_ENABLE_PLACEMENT_TRANSITIONS, &raw.enable_placement_transitions, self.enable_placement_transitions);
        return raw;
    }
    pub fn fromNative(raw: c.mln_style_transition_options) StyleTransitionOptions {
        return .{
            .duration_ms = if (raw.fields & c.MLN_STYLE_TRANSITION_OPTION_DURATION != 0) raw.duration_ms else null,
            .delay_ms = if (raw.fields & c.MLN_STYLE_TRANSITION_OPTION_DELAY != 0) raw.delay_ms else null,
            .enable_placement_transitions = if (raw.fields & c.MLN_STYLE_TRANSITION_OPTION_ENABLE_PLACEMENT_TRANSITIONS != 0) raw.enable_placement_transitions else null,
        };
    }
};

