/// Receiver wake callback copied by a successful owning call. The callback
/// schedules service by the receiver and returns without waiting for another
/// thread.
///
/// See `mln_wake` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/wake_8h.html).
pub const Wake = struct {
    context: ?*anyopaque = null,
    release_context: ?*const fn (?*anyopaque) void = null,
    callback: ?*const fn (context: ?*anyopaque) anyerror!void = null,
    pub fn toNative(self: Wake, roots: *callbacks.Roots) status.Error!c.mln_wake {
        var raw = std.mem.zeroes(c.mln_wake);
        raw.callback = if (self.callback != null) callbackTrampoline else null;
        if (!(self.callback == null)) {
            const retained = try roots.retain(Wake, self);
            raw.user_data = retained;
            raw.release_user_data = callbacks.Registration(Wake).releaseNative;
        }
        return raw;
    }
    fn callbackTrampoline(native_arg_0: marshal.CallbackArg(c.mln_wake_callback, 0)) callconv(.c) marshal.CallbackResult(c.mln_wake_callback) {
        return struct {
            fn invoke(callback_arg_0: marshal.CallbackArg(c.mln_wake_callback, 0)) anyerror!marshal.CallbackResult(c.mln_wake_callback) {
                const state = callbacks.Registration(Wake).get(callback_arg_0);
                const host = state.value.callback orelse {
                    return;
                };
                try host(state.value.context);
            }
        }.invoke(native_arg_0) catch |err| {
            callbacks.reportError("mln_wake_callback", err);
            return;
        };
    }
    /// Builds a `Wake` whose callbacks receive `context`, a pointer, as
    /// its own type. Each callback takes the context and then the arguments
    /// of its field, and may return any error; pass null to leave one unset.
    /// Native runs `release`, when it is not null, once it releases the
    /// registration.
    pub fn init(context: anytype, comptime callback: anytype, comptime release: ?fn (@TypeOf(context)) void) Wake {
        const Context = @TypeOf(context);
        if (@typeInfo(Context) != .pointer) @compileError("a Wake context must be a pointer");
        return .{
            .context = @ptrCast(@constCast(context)),
            .release_context = if (release == null) null else struct {
                fn call(erased: ?*anyopaque) void {
                    release.?(@as(Context, @ptrCast(@alignCast(erased.?))));
                }
            }.call,
            .callback = if (@TypeOf(callback) == @TypeOf(null)) null else struct {
                fn call(erased: ?*anyopaque) anyerror!void {
                    return callback(@as(Context, @ptrCast(@alignCast(erased.?))));
                }
            }.call,
        };
    }
};

/// WebGL context fields shared by OpenGL render targets in the browser.
///
/// See `mln_webgl_context_descriptor` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/render__target_8h.html).
pub const WebGlContextDescriptor = struct {
    kind: WebGlContextKind = .existing,
    /// Borrowed EMSCRIPTEN_WEBGL_CONTEXT_HANDLE for EXISTING. Must be positive.
    context: i32 = 0,
    /// Copied UTF-8 Emscripten target selector for TRANSFERRED_CANVAS. The HTML
    /// canvas must still be transferable when attachment starts.
    canvas_selector: []const u8 = &.{},
    pub fn toNative(self: WebGlContextDescriptor) status.Error!c.mln_webgl_context_descriptor {
        var raw = std.mem.zeroes(c.mln_webgl_context_descriptor);
        raw.kind = self.kind.toNative();
        raw.context = self.context;
        raw.canvas_selector = marshal.view(self.canvas_selector);
        return raw;
    }

    pub fn fromNative(allocator: std.mem.Allocator, raw: c.mln_webgl_context_descriptor) status.Error!WebGlContextDescriptor {
        return .{
            .kind = WebGlContextKind.fromNative(raw.kind),
            .context = raw.context,
            .canvas_selector = try marshal.copyView(allocator, raw.canvas_selector),
        };
    }
};

/// WebGL context placement.
///
/// See `mln_webgl_context_kind` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/render__target_8h.html).
pub const WebGlContextKind = enum(u32) {
    /// Use a host-created context on its current browser agent.
    existing = 0,
    /// Transfer the canvas named by canvas_selector to a native worker and
    /// create a WebGL 2 context there.
    transferred_canvas = 1,
    _,
    pub const fromNative = marshal.EnumMethods(@This()).fromNative;
    pub const toNative = marshal.EnumMethods(@This()).toNative;
};

/// WGL context fields shared by OpenGL render targets on Windows.
///
/// See `mln_wgl_context_descriptor` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/render__target_8h.html).
pub const WglContextDescriptor = struct {
    /// Borrowed HDC used to create the session context. Required. A dedicated
    /// owned texture makes its context current on this HDC from its core
    /// worker.
    device_context: ?*anyopaque,
    /// Borrowed HGLRC whose share group the session context joins. Required
    /// under shared ownership. A dedicated session joins no share group, so it
    /// must be null there.
    share_context: ?*anyopaque = null,
    /// Optional wglGetProcAddress-compatible function for the host loader.
    get_proc_address: ?*anyopaque = null,
    pub fn toNative(self: WglContextDescriptor) c.mln_wgl_context_descriptor {
        var raw = std.mem.zeroes(c.mln_wgl_context_descriptor);
        raw.device_context = self.device_context;
        raw.share_context = self.share_context;
        raw.get_proc_address = self.get_proc_address;
        return raw;
    }
    pub fn fromNative(raw: c.mln_wgl_context_descriptor) WglContextDescriptor {
        return .{
            .device_context = raw.device_context,
            .share_context = raw.share_context,
            .get_proc_address = raw.get_proc_address,
        };
    }
};

